    public function run($tahun = 2021, $conn = 1)
    {
        $this->dosen($tahun, $conn);
        $this->kar_tul_sas($tahun, $conn);
        $this->karya_seni($tahun, $conn);
        $this->karya_terapan($tahun, $conn);
        $this->kti($tahun, $conn);
        $this->penelitian($tahun, $conn);
        $this->pengabdian($tahun, $conn);
        $this->pengem_invensi_mitra($tahun, $conn);
        $this->preserv($tahun, $conn);
        $this->rekog($tahun, $conn);
        $this->paten($tahun, $conn);
        $this->iku($tahun, $conn);
        $this->dashboard($tahun, $conn);
    }

    public function dosen($tahun, $conn)
    {
        $sql = "
            SELECT
                sdm.id_sdm,
                ptk.id_sms,
                aktfptk.id_thn_ajaran,
                iks.nm_ikatan_kerja,
                stat.nm_stat_aktif,
                sdm.nm_sdm,
                CASE
                    sdm.jk
                    WHEN 'L' THEN 'Laki-Laki'
                    WHEN 'P' THEN 'Perempuan'
                END AS jk,
                datediff(MONTH, sdm.tgl_lahir, getdate()) / 12 - CASE
                    WHEN month(sdm.tgl_lahir) = month(getdate())
                    AND day(sdm.tgl_lahir) > day(getdate()) THEN 1
                    ELSE 0
                END AS usia,
                (
                    SELECT
                        sdm.nidn
                    WHERE
                        LEFT(sdm.nidn, 2) <= 87
                ) AS nidn,
                (
                    SELECT
                        sdm.nidn
                    WHERE
                        LEFT(sdm.nidn, 2) IN (88, 89)
                ) AS nidk,
                fak.nm_lemb AS fakultas,
                jur.nm_jur AS jurusan,
                CONCAT(prodi.nm_lemb, ' (', jp.nm_jenj_didik, ')') AS prodi
            FROM
                pdrd.sdm AS sdm WITH(NOLOCK)
                JOIN pdrd.reg_ptk AS ptk WITH(NOLOCK) ON ptk.id_sdm = sdm.id_sdm
                JOIN ref.status_kepegawaian AS skep WITH(NOLOCK) ON skep.id_stat_pegawai = ptk.id_stat_pegawai
                JOIN pdrd.keaktifan_ptk AS aktfptk WITH(NOLOCK) ON aktfptk.id_reg_ptk = ptk.id_reg_ptk
                LEFT JOIN ref.jenis_sdm AS jsdm WITH(NOLOCK) ON jsdm.id_jns_sdm = sdm.id_jns_sdm
                LEFT JOIN ref.status_keaktifan_pegawai AS aktf WITH(NOLOCK) ON aktf.id_stat_aktif = sdm.id_stat_aktif
                LEFT JOIN pdrd.sms AS prodi WITH(NOLOCK) ON prodi.id_sms = ptk.id_sms AND prodi.soft_delete = 0
                LEFT JOIN pdrd.sms AS fak WITH(NOLOCK) ON fak.id_sms = prodi.id_induk_sms AND fak.soft_delete = 0
                LEFT JOIN ref.jurusan AS jur WITH(NOLOCK) ON jur.id_jur = prodi.id_jur AND jur.expired_date IS NULL
                LEFT JOIN ref.jenjang_pendidikan AS jp WITH(NOLOCK) ON jp.id_jenj_didik = prodi.id_jenj_didik
                LEFT JOIN ref.ikatan_kerja_sdm AS iks WITH(NOLOCK) ON iks.id_ikatan_kerja = ptk.id_ikatan_kerja
                LEFT JOIN ref.status_keaktifan_pegawai AS stat WITH(NOLOCK) ON stat.id_stat_aktif = sdm.id_stat_aktif
            WHERE
                sdm.soft_delete = 0
                AND sdm.id_stat_aktif IN (1, 24, 25, 27)
                AND ptk.soft_delete = 0
                AND ptk.id_jns_keluar IS NULL
                AND (
                    ptk.tgl_ptk_keluar IS NULL
                    OR ptk.tgl_ptk_keluar > GETDATE()
                )
                AND ptk.id_ikatan_kerja IN ('A', 'F', 'I', 'G')
                AND aktfptk.soft_delete = 0
                AND aktfptk.a_sp_homebase = 1
                AND aktfptk.id_thn_ajaran = " . $tahun . "
                AND jsdm.expired_date IS NULL
                AND aktf.expired_date IS NULL
                AND jp.expired_date IS NULL
                AND iks.expired_date IS NULL
                AND stat.expired_date IS NULL
            ";

        if ($conn == 1) {
            $data = DB::connection('sqlsrv_live')->select($sql);
        } else {
            $data = DB::select($sql);
        }

        foreach ($data as $each_data) {
            Iku5Dosen::updateOrInsert([
                'id_sdm' => $each_data->id_sdm,
                'id_thn_ajaran' => $each_data->id_thn_ajaran,
            ], [
                'id_sms' => $each_data->id_sms,
                'id_dosen' => guid(),
                'nm_ikatan_kerja' => $each_data->nm_ikatan_kerja,
                'nm_stat_aktif' => $each_data->nm_stat_aktif,
                'nm_sdm' => $each_data->nm_sdm,
                'jk' => $each_data->jk,
                'usia' => $each_data->usia,
                'nidn' => $each_data->nidn,
                'nidk' => $each_data->nidk,
                'fakultas' => $each_data->fakultas,
                'jurusan' => $each_data->jurusan,
                'prodi' => $each_data->prodi,
                'last_sync' => currDateTime(),
            ]);
        }
    }

    public function kar_tul_sas($tahun, $conn)
    {
        $sql = "
                SELECT
                    l.id_publikasi,tkeaktifan.id_thn_ajaran,tsdm.nidn,treg.id_reg_ptk,tsdm.id_sdm,tsp.id_sp,tsms.id_sms,l.id_jns_pub,
                    l.judul,l.tgl_terbit,sal.urutan,sal.peran_tulis,l.id_media_pub
                FROM pdrd.sdm tsdm WITH (NOLOCK)
                    LEFT JOIN pdrd.reg_ptk treg WITH (NOLOCK) ON treg.id_sdm = tsdm.id_sdm AND treg.soft_delete = 0
                    LEFT JOIN pdrd.keaktifan_ptk tkeaktifan WITH (NOLOCK) ON tkeaktifan.id_reg_ptk = treg.id_reg_ptk AND tkeaktifan.soft_delete = 0
                    LEFT JOIN pdrd.satuan_pendidikan tsp WITH (NOLOCK) ON tsp.id_sp = treg.id_sp AND tsp.soft_delete = 0
                    LEFT JOIN pdrd.sms tsms WITH (NOLOCK) ON tsms.id_sms = treg.id_sms AND tsms.soft_delete = 0
                    join pdrd.tulis_pub sal on sal.id_sdm = tsdm.id_sdm and sal.soft_delete = 0 and sal.id_katgiat in ('130200')
                    JOIN pdrd.publikasi l on l.id_publikasi = sal.id_publikasi and l.soft_delete = 0 
                WHERE tkeaktifan.id_thn_ajaran = " . $tahun . "
                    AND tkeaktifan.a_sp_homebase = 1
                    AND tsdm.soft_delete = 0
                    AND tsdm.id_jns_sdm = 12
                    AND tsp.stat_sp = 'A'
                    AND tsms.id_jns_sms = 3
                    AND LEFT(tsp.id_wil,2) <> '99'
                    AND tsdm.id_stat_aktif IN('1','20','24','25','27')
                    AND tsp.npsn = '001026'
                    AND treg.id_jns_keluar IS NULL
                    AND (
                        l.tgl_terbit >= '2021-01-01'
                        AND l.tgl_terbit <= '2021-12-31'
                    )
        ";

        if ($conn == 1) {
            $data = DB::connection('sqlsrv_live')->select($sql);
        } else {
            $data = DB::select($sql);
        }

        
        foreach ($data as $each_data) {
            Iku5DosenKarTulSas::updateOrInsert([
                'id_publikasi' => $each_data->id_publikasi,
                'id_thn_ajaran' => $each_data->id_thn_ajaran,
                'id_sdm' => $each_data->id_sdm,
            ], [
                'nidn' => $each_data->nidn,
                'id_reg_ptk' => $each_data->id_reg_ptk,
                'id_kar_tul_sas' => guid(),
                'id_sp' => $each_data->id_sp,
                'id_sms' => $each_data->id_sms,
                'id_jns_pub' => $each_data->id_jns_pub,
                'judul' => $each_data->judul,
                'tgl_terbit' => $each_data->tgl_terbit,
                'urutan' => $each_data->urutan,
                'peran_tulis' => $each_data->peran_tulis,
                'id_media_pub' => $each_data->id_media_pub,
                'soft_delete' => 0,
                'last_sync' => currDateTime(),
                
            ]);
        }
    }

    public function karya_seni($tahun, $conn)
