    public function kti($tahun, $conn)
    {
        $sql = "
                SELECT
                    l.id_publikasi,tkeaktifan.id_thn_ajaran,tsdm.nidn,treg.id_reg_ptk,tsdm.id_sdm,tsp.id_sp,tsms.id_sms,l.id_jns_pub,
                    l.judul,l.tgl_terbit,sal.urutan,sal.peran_tulis,l.id_media_pub, sal.id_katgiat
                FROM pdrd.sdm tsdm WITH (NOLOCK)
                    LEFT JOIN pdrd.reg_ptk treg WITH (NOLOCK) ON treg.id_sdm = tsdm.id_sdm AND treg.soft_delete = 0
                    LEFT JOIN pdrd.keaktifan_ptk tkeaktifan WITH (NOLOCK) ON tkeaktifan.id_reg_ptk = treg.id_reg_ptk AND tkeaktifan.soft_delete = 0
                    LEFT JOIN pdrd.satuan_pendidikan tsp WITH (NOLOCK) ON tsp.id_sp = treg.id_sp AND tsp.soft_delete = 0
                    LEFT JOIN pdrd.sms tsms WITH (NOLOCK) ON tsms.id_sms = treg.id_sms AND tsms.soft_delete = 0
                    join pdrd.tulis_pub sal on sal.id_sdm = tsdm.id_sdm and sal.soft_delete = 0 and sal.id_katgiat in ('140600','110801','140903','140901','140902','22310302','22320102','22310201','22320201','22320101','22310301','22310202','22310601','22320202','22310501','22310101','22310102','22310103','110802','22330201','22330101','110405','110401','120122','120103','120104','120113','120114','120102','120112','120105','120107','120106','120111','120109','120110','120108','120101','120121','120117','120118','120119','120120','22223900','22221100','22221200','22221300','110400','150203','150202','22310300','22310400','22310100','22310200','22224300','22310500','130500','22320100','22320200','120200','120300','120100','150201','150200','22220700','140900','150100','110900','22310600','150301','150302','150303','150305','150304','150300','22220200','22220400','22220600','22220300','22220500','22330200','22330300','22330100','22330000','22230200','22230100','22210600','22210800','22210500','22210700','22221600','22211900','22211800','22212800','22212200','22212100','22212400','22212300','22211100','22211200','22211300','22211400','22212700','22212600','22212500','22212000','22210200','22210400','22310000','22320000','140601','140602','110407','110403','130301','130303','130302','130304','130306','130305','110406','110402')
                    JOIN pdrd.publikasi l on l.id_publikasi = sal.id_publikasi and l.soft_delete = 0 
                WHERE tkeaktifan.id_thn_ajaran = " . $tahun . "
                    AND tkeaktifan.a_sp_homebase = 1
                    AND tsdm.soft_delete = 0
                    AND tsdm.id_jns_sdm = 12
                    AND tsp.stat_sp = 'A'
                    AND tsms.id_jns_sms = 3
                    AND LEFT(tsp.id_wil,2) <> '99'
                    AND tsdm.id_stat_aktif IN('1','20','24','25','27')
                    AND tsp.npsn = '001026'
                    AND treg.id_jns_keluar IS NULL
                    AND l.id_jns_pub !='9999'
                    AND (
                        l.tgl_terbit >= '2021-01-01'
                        AND l.tgl_terbit <= '2021-12-31'
                    )
        ";

        if ($conn == 1) {
            $data = DB::connection('sqlsrv_live')->select($sql);
        } else {
            $data = DB::select($sql);
        }
        // print_r($data);
        foreach ($data as $each_data) {
