            //     continue;
            // }

            Iku5DosenKTI::updateOrInsert([
                'id_publikasi' => $each_data->id_publikasi,
                'id_thn_ajaran' => $each_data->id_thn_ajaran,
                'id_sdm' => $each_data->id_sdm,
                
