    public function pengabdian($tahun, $conn)
    {
        $sql = "
            SELECT 
                x.id_sdm, x.id_reg_ptk, max(x.id_thn_kegiatan) as thn_kegiatan, max(x.id_jabfung) as jabfung_id, 
                max(x.id_lemb_iptek) as id_sp_keg, max(x.id_sp) as id_sp_asal, max(x.jns_litabmas) as jns_litabmas
            FROM 
                (SELECT tsdm.nidn, treg.id_reg_ptk, tsdm.id_sdm, l.id_litabmas, l.id_lemb_iptek, tsp.id_sp, tjabfung.id_jabfung, l.id_thn_kegiatan, l.jns_litabmas
            FROM pdrd.sdm tsdm WITH (NOLOCK)
                LEFT JOIN pdrd.reg_ptk treg WITH (NOLOCK) ON treg.id_sdm = tsdm.id_sdm AND treg.soft_delete = 0
                LEFT JOIN pdrd.keaktifan_ptk tkeaktifan WITH (NOLOCK) ON tkeaktifan.id_reg_ptk = treg.id_reg_ptk AND tkeaktifan.soft_delete = 0
                LEFT JOIN pdrd.satuan_pendidikan tsp WITH (NOLOCK) ON tsp.id_sp = treg.id_sp AND tsp.soft_delete = 0
                LEFT JOIN pdrd.sms tsms WITH (NOLOCK) ON tsms.id_sms = treg.id_sms AND tsms.soft_delete = 0
                join pdrd.sdm_anggota_litabmas sal on sal.id_sdm = tsdm.id_sdm and sal.soft_delete = 0 --and sal.peran_litabmas != 'K'
                JOIN pdrd.litabmas l on l.id_litabmas = sal.id_litabmas and l.soft_delete = 0 and l.jns_litabmas = 'M'
                LEFT JOIN (
                    SELECT MAX(rwy_fungsional.id_jabfung) AS id_jabfung, id_sdm
                    FROM pdrd.rwy_fungsional
                    LEFT JOIN ref.jabfung ON jabfung.id_jabfung = rwy_fungsional.id_jabfung
                    WHERE tmt_sk_jabfung <= getdate()
                    AND jabfung.expired_date IS NULL
                    AND jabfung.id_kel_prof = '2'
                    AND soft_delete = 0
                    GROUP BY id_sdm
                ) AS tjabfung ON tjabfung.id_sdm=tsdm.id_sdm
            WHERE tkeaktifan.id_thn_ajaran = " . $tahun . "
                AND tkeaktifan.a_sp_homebase = 1
                AND tsdm.soft_delete = 0
                AND tsdm.id_jns_sdm = 12
                AND tsp.stat_sp = 'A'
                AND tsms.id_jns_sms = 3
                AND LEFT(tsp.id_wil,2) <> '99'
                AND tsdm.id_stat_aktif IN('1','20','24','25','27')
                AND tsp.npsn = '001026'
                AND treg.id_jns_keluar IS NULL
            ) as x 
        where x.id_lemb_iptek != x.id_sp
        group by x.id_sdm, x.id_reg_ptk
        ";

        if ($conn == 1) {
            $data = DB::connection('sqlsrv_live')->select($sql);
        } else {
            $data = DB::select($sql);
        }

        
        foreach ($data as $each_data) {
            Iku5DosenPengabdian::updateOrInsert([
                'id_sdm' => $each_data->id_sdm,
            ], [
                'id_reg_ptk' => $each_data->id_reg_ptk,
                'id_pengabdian' => guid(),
                'id_thn_kegiatan' => $each_data->thn_kegiatan,
                'jabfung_id' => $each_data->jabfung_id,
                'id_sp_keg' => $each_data->id_sp_keg,
                'id_sp_asal' => $each_data->id_sp_asal,
                'jns_litabmas' => $each_data->jns_litabmas,
                'soft_delete' => 0,
                'last_sync' => currDateTime(),
            ]);
        }
    }

    public function pengem_invensi_mitra($tahun, $conn)
    {
        $sql = "
                SELECT 
                    tsdm.nidn, treg.id_reg_ptk, tsdm.id_sdm, tsp.id_sp, tsms.id_sms, tkeaktifan.id_thn_ajaran,am.judul_akt_mhs, jam.nm_jns_akt_mhs, am.tgl_sk_tugas
                FROM 
                    pdrd.sdm tsdm WITH (NOLOCK)
                    LEFT JOIN pdrd.reg_ptk treg WITH (NOLOCK) ON treg.id_sdm = tsdm.id_sdm AND treg.soft_delete = 0
                    LEFT JOIN pdrd.keaktifan_ptk tkeaktifan WITH (NOLOCK) ON tkeaktifan.id_reg_ptk = treg.id_reg_ptk AND tkeaktifan.soft_delete = 0
                    LEFT JOIN pdrd.satuan_pendidikan tsp WITH (NOLOCK) ON tsp.id_sp = treg.id_sp AND tsp.soft_delete = 0
                    LEFT JOIN pdrd.sms tsms WITH (NOLOCK) ON tsms.id_sms = treg.id_sms AND tsms.soft_delete = 0
                    join pdrd.bimbing_mhs sal on sal.id_sdm = tsdm.id_sdm and sal.soft_delete = 0 and sal.id_katgiat in 
                    (select id_katgiat from ref.kategori_kegiatan where id_katgiat in (
                    select id_katgiat from ref.kategori_tabel where id_katgiat in ('111200','130000','110108','110107','110106','110105','22221000','130300','130400','22224200','22224000','22224100','22220800','22220900','110300','110200','110600','22223300','22223100','22223200','22241300','22221700','110800','22250200','22250300','22250400','110700','22250100','22241200','22240300','22240400','22241000','22240200','22240100','22241100','22221900','22222800','22222900','22223000','22250500','22210300','22211500','22211700','22210403','22410000','22210000','130401','130402','130403','130200','130300')
                    and nm_tbl != 'kelola_unit_fungsi') and id_jns_sdm = 12)
                    join pdrd.akt_mhs am on am.id_akt_mhs = sal.id_akt_mhs and am.soft_delete = 0
                    join ref.jenis_akt_mhs jam on jam.id_jns_akt_mhs = am.id_jns_akt_mhs
                WHERE tkeaktifan.id_thn_ajaran = " . $tahun . "
                    AND tkeaktifan.a_sp_homebase = 1
                    AND tsdm.soft_delete = 0
                    AND tsdm.id_jns_sdm = 12
                    AND tsp.stat_sp = 'A'
                    AND tsms.id_jns_sms = 3
                    AND LEFT(tsp.id_wil,2) <> '99'
                    AND tsdm.id_stat_aktif IN('1','20','24','25','27')
                    AND tsp.npsn = '001026'
                    AND treg.id_jns_keluar IS NULL
                    
        ";

        if ($conn == 1) {
            $data = DB::connection('sqlsrv_live')->select($sql);
        } else {
            $data = DB::select($sql);
        }

        foreach ($data as $each_data) {
            Iku5DosenPengemInvensiMitra::updateOrInsert([
                'id_thn_ajaran' => $each_data->id_thn_ajaran,
                'id_sdm' => $each_data->id_sdm,
            ], [
                'nidn' => $each_data->nidn,
                'id_reg_ptk' => $each_data->id_reg_ptk,
                'id_pengem_invensi_mitra' => guid(),
                'id_sp' => $each_data->id_sp,
                'id_sms' => $each_data->id_sms,
                'judul_akt_mhs' => $each_data->judul_akt_mhs,
                'nm_jns_akt_mhs' => $each_data->nm_jns_akt_mhs,
                'tgl_sk_tugas' => $each_data->tgl_sk_tugas,
                'peran_tulis' => $each_data->peran_tulis,
                'soft_delete' => 0,
                'last_sync' => currDateTime(),
            ]);
        }
    }

    public function preserv($tahun, $conn)
    {
        $sql = "
            SELECT 
                    l.id_publikasi, tkeaktifan.id_thn_ajaran, tsdm.nidn, treg.id_reg_ptk, tsdm.id_sdm, tsp.id_sp, tsms.id_sms, l.id_jns_pub, 
