                    LEFT JOIN pdrd.sms tsms WITH (NOLOCK) ON tsms.id_sms = treg.id_sms AND tsms.soft_delete = 0
                    join pdrd.tulis_pub sal on sal.id_sdm = tsdm.id_sdm and sal.soft_delete = 0 and sal.id_katgiat in ('120707','120709','120708','120704','120706','120705','120504','120501','120503','120502','120400','141000','22222100')
                    JOIN pdrd.publikasi l on l.id_publikasi = sal.id_publikasi and l.soft_delete = 0 
