    public function dashboard($tahun, $conn)
    {
        $sql = "
            SELECT
             dosen.id_sms,
                dosen.id_thn_ajaran AS id_tahun_anggaran,
                (
                    SELECT 
                        COUNT(nm_ikatan_kerja) 
                    FROM 
                        temp_iku.iku5dosen
                    WHERE 
                        nm_ikatan_kerja IS NOT NULL
                        AND id_sms = dosen.id_sms
                ) AS total_dosen_tetap,
                (
                    SELECT 
                        COUNT(c_dosen_kti) 
                    FROM 
                        temp_iku.iku5dosen 
                    WHERE
                        c_dosen_kti != 0 
                        AND id_sms = dosen.id_sms
                ) AS total_luaran_kti,
                (
                    SELECT 
                        COUNT(c_dosen_karya_terapan)
                    FROM 
                        temp_iku.iku5dosen
                    WHERE
                        c_dosen_karya_terapan != 0 
                        AND id_sms = dosen.id_sms
                ) AS total_luaran_karya_terapan,
                (
                    SELECT 
                        COUNT(c_dosen_karya_seni) 
                    FROM 
                        temp_iku.iku5dosen 
                    WHERE 
                        c_dosen_karya_seni != 0 
                        AND id_sms = dosen.id_sms
                ) AS total_luaran_karya_seni,
                (
                    SELECT 
                        COUNT(c_dosen_paten) 
                    FROM 
                        temp_iku.iku5dosen 
                    WHERE 
                        c_dosen_paten != 0 
                        AND id_sms = dosen.id_sms
                ) AS total_luaran_paten
            FROM
                temp_iku.iku5dosen AS dosen WITH(NOLOCK)
            WHERE 
                dosen.id_thn_ajaran = " . $tahun . "
            GROUP BY
                dosen.id_sms, dosen.id_thn_ajaran
        ";

            $data = DB::select($sql);


        // foreach ($sql as $each_data) {
        //     $presentase[$each_data->id_sms][$each_data->id_tahun_anggaran] = round(($each_data->total_luaran_kti + $each_data->total_luaran_karya_seni + $each_data->total_luaran_karya_terapan +$each_data->total_luaran_paten)/($each_data->total_dosen_tetap));
        // }        

        foreach ($data as $each_data) {
            DetailIku5::updateOrInsert([
                'id_sms' => $each_data->id_sms,
                'id_tahun_anggaran' => $each_data->id_tahun_anggaran,
            ], [
                'id_detail_iku_5' => guid(),
                'total_dosen_tetap' => $each_data->total_dosen_tetap,
                'total_luaran_kti' => $each_data->total_luaran_kti,
                'total_luaran_karya_terapan' => $each_data->total_luaran_karya_terapan,
                'total_luaran_karya_seni' => $each_data->total_luaran_karya_seni,
                'total_luaran_paten' => $each_data->total_luaran_paten,
                'create_date' => currDateTime(),
                'last_update' => currDateTime(),
                'expired_date' => currDateTime(),
                'last_sync' => currDateTime(),
            ]);
        }
        echo " Data dashboard_iku5 berhasil diperbaharui\n";
    }
}






